set_project("isolated-cpp26-smoke")
set_languages("cxx26")
add_rules("mode.debug", "mode.release")
toolchain("isolated-clang")
    set_kind("standalone")
    set_toolset("cc", "clang-cl.exe")
    set_toolset("cxx", "clang-cl.exe")
    set_toolset("ld", "lld-link.exe")
toolchain_end()
target("hello")
    set_kind("binary")
    set_toolchains("isolated-clang")
    set_targetdir("out")
    add_files("main.cpp")
    add_cxxflags("/GS-", {force = true})
    add_ldflags("/nodefaultlib", "/entry:mainCRTStartup", "/subsystem:console", {force = true})
target_end()
